{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill defines an immigration officer as any state, local, or federal law enforcement officer seeking to enforce immigration law.",
      "rationale": "Conveys the full operative definition. The named federal agencies are illustrative examples, not additional limits on its scope."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "This bill would require school directors for local education agencies (LEAs) and public charter schools to immediately notify all students, parents, educators, employees, and contractors if an immigration officer is on the school grounds.",
      "rationale": "Identifies the responsible directors, immediate notification duty, all recipient groups, and school-grounds trigger. Omitting the statutory cross-references does not materially change the described duty."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "It specifies that this notification requirement and any related policies are not considered sanctuary policies and do not subject school officials or employees to penalties associated with sanctuary policies.",
      "rationale": "Conveys both the non-sanctuary classification of the requirement and implementing policies and protection from sanctuary-policy penalties. 'School officials or employees' reasonably encompasses the listed board members, directors, and employees."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "This act would take effect upon becoming law.",
      "rationale": "States the effective-date provision accurately."
    }
  ]
}
